-- =====================================================================
-- PrivateChat schema (Supabase / Postgres)
--
-- Run once in: Supabase Dashboard -> SQL Editor -> New query -> paste -> Run.
-- Safe to run again. Every object is prefixed pc_ so it never collides with other
-- apps that share the same Supabase project (e.g. an older chat app's "profiles" table).
--
-- Security model
--   * Row Level Security is ON for every table; anon has no access at all.
--   * Clients can only change their own display name / photo (column-level grants).
--   * User ID is generated by the database and can never be edited.
--   * You can message someone only after you saved them as a contact.
--   * Contacts are added only through pc_add_contact(); messages are readable only
--     by their sender and receiver; chat photos only by the two people in that chat.
-- =====================================================================

-- ---------------------------------------------------------------- tables
create table if not exists public.pc_profiles (
  id            uuid primary key references auth.users (id) on delete cascade,
  user_id       text not null unique,
  display_name  text not null,
  avatar_path   text,
  onboarded_at  timestamptz,
  last_seen_at  timestamptz not null default now(),
  created_at    timestamptz not null default now(),
  constraint pc_profiles_user_id_format  check (user_id ~ '^[a-z0-9_]{3,40}$'),
  constraint pc_profiles_display_name_len check (char_length(btrim(display_name)) between 1 and 50),
  constraint pc_profiles_avatar_path_fmt  check (avatar_path is null or avatar_path ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]{1,100}$')
);

create table if not exists public.pc_contacts (
  owner_id    uuid not null references public.pc_profiles (id) on delete cascade,
  contact_id  uuid not null references public.pc_profiles (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (owner_id, contact_id),
  constraint pc_contacts_not_self check (owner_id <> contact_id)
);

create table if not exists public.pc_messages (
  id          uuid primary key default gen_random_uuid(),
  sender_id   uuid not null default auth.uid() references public.pc_profiles (id) on delete cascade,
  receiver_id uuid not null references public.pc_profiles (id) on delete cascade,
  body        text,
  image_path  text,
  created_at  timestamptz not null default now(),
  read_at     timestamptz,
  constraint pc_messages_not_self    check (sender_id <> receiver_id),
  constraint pc_messages_has_content check (body is not null or image_path is not null),
  constraint pc_messages_body_len    check (body is null or char_length(btrim(body)) between 1 and 4000),
  constraint pc_messages_image_path  check (image_path is null or image_path ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]{1,100}$')
);

create index if not exists pc_contacts_contact_idx  on public.pc_contacts (contact_id);
create index if not exists pc_messages_pair_idx     on public.pc_messages (sender_id, receiver_id, created_at desc);
create index if not exists pc_messages_pair_rev_idx on public.pc_messages (receiver_id, sender_id, created_at desc);
create index if not exists pc_messages_unread_idx   on public.pc_messages (receiver_id, sender_id) where read_at is null;

-- ---------------------------------------------------- row level security
alter table public.pc_profiles enable row level security;
alter table public.pc_contacts enable row level security;
alter table public.pc_messages enable row level security;

-- Table privileges: start from nothing, then grant only what the app needs.
revoke all on public.pc_profiles from public, anon, authenticated;
revoke all on public.pc_contacts from public, anon, authenticated;
revoke all on public.pc_messages from public, anon, authenticated;

grant select on public.pc_profiles to authenticated;
grant update (display_name, avatar_path, onboarded_at) on public.pc_profiles to authenticated;
grant select, delete on public.pc_contacts to authenticated;      -- adding goes through pc_add_contact()
grant select, insert on public.pc_messages to authenticated;      -- read_at is set only by pc_mark_read()

-- Profiles: you see yourself, people you saved, and people you exchanged messages with.
drop policy if exists pc_profiles_select on public.pc_profiles;
create policy pc_profiles_select on public.pc_profiles for select to authenticated
using (
  id = (select auth.uid())
  or exists (select 1 from public.pc_contacts c
             where c.owner_id = (select auth.uid()) and c.contact_id = pc_profiles.id)
  or exists (select 1 from public.pc_messages m
             where (m.receiver_id = (select auth.uid()) and m.sender_id = pc_profiles.id)
                or (m.sender_id = (select auth.uid()) and m.receiver_id = pc_profiles.id))
);

drop policy if exists pc_profiles_update on public.pc_profiles;
create policy pc_profiles_update on public.pc_profiles for update to authenticated
using (id = (select auth.uid()))
with check (
  id = (select auth.uid())
  and (avatar_path is null or avatar_path like (select auth.uid())::text || '/%')
);

-- Contacts: only your own list.
drop policy if exists pc_contacts_select on public.pc_contacts;
create policy pc_contacts_select on public.pc_contacts for select to authenticated
using (owner_id = (select auth.uid()));

drop policy if exists pc_contacts_delete on public.pc_contacts;
create policy pc_contacts_delete on public.pc_contacts for delete to authenticated
using (owner_id = (select auth.uid()));

-- Messages: only sender and receiver can read; you can only send as yourself, to a saved contact.
drop policy if exists pc_messages_select on public.pc_messages;
create policy pc_messages_select on public.pc_messages for select to authenticated
using (sender_id = (select auth.uid()) or receiver_id = (select auth.uid()));

drop policy if exists pc_messages_insert on public.pc_messages;
create policy pc_messages_insert on public.pc_messages for insert to authenticated
with check (
  sender_id = (select auth.uid())
  and exists (select 1 from public.pc_contacts c
              where c.owner_id = (select auth.uid()) and c.contact_id = receiver_id)
  and (image_path is null or image_path like (select auth.uid())::text || '/%')
);

-- ------------------------------------------------------------- functions
-- Name slug + 5 random characters, e.g. "ratan_kumar_8f3k2". Internal only (not callable by clients).
create or replace function public.pc_generate_user_id(p_name text)
returns text
language plpgsql
volatile
set search_path = public
as $$
declare
  v_slug      text;
  v_alphabet  constant text := 'abcdefghijklmnopqrstuvwxyz0123456789';
  v_suffix    text;
  v_candidate text;
  i           int;
  attempt     int;
begin
  v_slug := lower(regexp_replace(coalesce(p_name, ''), '[^a-zA-Z0-9]+', '_', 'g'));
  v_slug := btrim(left(btrim(v_slug, '_'), 24), '_');
  if char_length(v_slug) < 2 then
    v_slug := 'user';
  end if;

  for attempt in 1..25 loop
    v_suffix := '';
    for i in 1..5 loop
      v_suffix := v_suffix || substr(v_alphabet, 1 + floor(random() * 36)::int, 1);
    end loop;
    v_candidate := v_slug || '_' || v_suffix;
    if not exists (select 1 from public.pc_profiles p where p.user_id = v_candidate) then
      return v_candidate;
    end if;
  end loop;
  raise exception 'could not generate a unique user id';
end;
$$;

-- Creates the caller's profile on first use (with an auto-generated User ID); returns it every time after.
-- Only people who actually open PrivateChat get a profile, even if auth.users is shared with other apps.
create or replace function public.pc_ensure_profile()
returns public.pc_profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid   uuid := auth.uid();
  v_row   public.pc_profiles;
  v_meta  jsonb;
  v_email text;
  v_name  text;
  attempt int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select * into v_row from public.pc_profiles p where p.id = v_uid;
  if found then
    return v_row;
  end if;

  select u.raw_user_meta_data, u.email into v_meta, v_email from auth.users u where u.id = v_uid;
  v_name := left(btrim(coalesce(
    nullif(btrim(v_meta ->> 'full_name'), ''),
    nullif(btrim(v_meta ->> 'name'), ''),
    nullif(split_part(coalesce(v_email, ''), '@', 1), ''),
    'New user')), 50);
  if v_name = '' then
    v_name := 'New user';
  end if;

  for attempt in 1..5 loop
    begin
      insert into public.pc_profiles (id, user_id, display_name)
      values (v_uid, public.pc_generate_user_id(v_name), v_name)
      returning * into v_row;
      return v_row;
    exception when unique_violation then
      select * into v_row from public.pc_profiles p where p.id = v_uid;
      if found then
        return v_row;
      end if;
    end;
  end loop;
  raise exception 'could not create profile';
end;
$$;

-- Edit your own profile. Runs with your permissions, so RLS and column grants still apply.
create or replace function public.pc_update_profile(
  p_display_name      text    default null,
  p_avatar_path       text    default null,
  p_clear_avatar      boolean default false,
  p_finish_onboarding boolean default false
)
returns public.pc_profiles
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_row public.pc_profiles;
begin
  update public.pc_profiles p set
    display_name = coalesce(nullif(btrim(p_display_name), ''), p.display_name),
    avatar_path  = case when p_clear_avatar then null
                        when p_avatar_path is not null then p_avatar_path
                        else p.avatar_path end,
    onboarded_at = case when p_finish_onboarding and p.onboarded_at is null then now() else p.onboarded_at end
  where p.id = auth.uid()
  returning * into v_row;

  if not found then
    raise exception 'profile not found' using errcode = 'P0002';
  end if;
  return v_row;
end;
$$;

-- Exact-match lookup by User ID. Returns no presence info and never lists anyone.
create or replace function public.pc_find_user(p_user_id text)
returns table (id uuid, user_id text, display_name text, avatar_path text)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.user_id, p.display_name, p.avatar_path
  from public.pc_profiles p
  where auth.uid() is not null
    and p.onboarded_at is not null
    and p.user_id = lower(ltrim(btrim(p_user_id), '@'))
  limit 1;
$$;

create or replace function public.pc_add_contact(p_contact_id uuid)
returns table (id uuid, user_id text, display_name text, avatar_path text, last_seen_at timestamptz, added_at timestamptz)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_contact_id = v_uid then
    raise exception 'you cannot add yourself' using errcode = '22023';
  end if;
  if not exists (select 1 from public.pc_profiles t where t.id = p_contact_id and t.onboarded_at is not null) then
    raise exception 'user not found' using errcode = 'P0002';
  end if;

  insert into public.pc_contacts (owner_id, contact_id) values (v_uid, p_contact_id)
  on conflict do nothing;

  return query
    select p.id, p.user_id, p.display_name, p.avatar_path, p.last_seen_at, c.created_at
    from public.pc_contacts c
    join public.pc_profiles p on p.id = c.contact_id
    where c.owner_id = v_uid and c.contact_id = p_contact_id;
end;
$$;

create or replace function public.pc_remove_contact(p_contact_id uuid)
returns void
language sql
security invoker
set search_path = public
as $$
  delete from public.pc_contacts c where c.owner_id = auth.uid() and c.contact_id = p_contact_id;
$$;

create or replace function public.pc_list_contacts()
returns table (id uuid, user_id text, display_name text, avatar_path text, last_seen_at timestamptz, added_at timestamptz)
language sql
stable
security invoker
set search_path = public
as $$
  select p.id, p.user_id, p.display_name, p.avatar_path, p.last_seen_at, c.created_at
  from public.pc_contacts c
  join public.pc_profiles p on p.id = c.contact_id
  where c.owner_id = auth.uid()
  order by lower(p.display_name), p.user_id;
$$;

-- A profile you are allowed to see (contact, or someone you exchanged messages with).
create or replace function public.pc_get_profile(p_id uuid)
returns table (id uuid, user_id text, display_name text, avatar_path text, last_seen_at timestamptz)
language sql
stable
security invoker
set search_path = public
as $$
  select p.id, p.user_id, p.display_name, p.avatar_path, p.last_seen_at
  from public.pc_profiles p
  where p.id = p_id;
$$;

create or replace function public.pc_get_messages(
  p_partner uuid,
  p_before  timestamptz default null,
  p_limit   integer     default 50
)
returns setof public.pc_messages
language sql
stable
security invoker
set search_path = public
as $$
  select m.*
  from public.pc_messages m
  where ((m.sender_id = auth.uid() and m.receiver_id = p_partner)
      or (m.sender_id = p_partner and m.receiver_id = auth.uid()))
    and (p_before is null or m.created_at < p_before)
  order by m.created_at desc, m.id desc
  limit least(greatest(coalesce(p_limit, 50), 1), 200);
$$;

create or replace function public.pc_send_message(
  p_receiver   uuid,
  p_body       text default null,
  p_image_path text default null
)
returns public.pc_messages
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_row public.pc_messages;
begin
  insert into public.pc_messages (receiver_id, body, image_path)
  values (p_receiver, nullif(btrim(p_body), ''), p_image_path)
  returning * into v_row;
  return v_row;
end;
$$;

-- Marks messages from p_partner to you as read (server clock). Returns how many changed.
create or replace function public.pc_mark_read(p_partner uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  n integer;
begin
  update public.pc_messages m set read_at = now()
  where m.receiver_id = auth.uid() and m.sender_id = p_partner and m.read_at is null;
  get diagnostics n = row_count;
  return n;
end;
$$;

-- "Online" = last heartbeat within ~70s. Uses the server clock so clients cannot fake it.
create or replace function public.pc_heartbeat()
returns void
language sql
security definer
set search_path = public
as $$
  update public.pc_profiles p set last_seen_at = now() where p.id = auth.uid();
$$;

-- One row per conversation: last message + unread count.
create or replace function public.pc_chat_summaries()
returns table (
  partner_id      uuid,
  last_message_id uuid,
  last_body       text,
  last_has_image  boolean,
  last_sender_id  uuid,
  last_at         timestamptz,
  unread_count    bigint
)
language sql
stable
security invoker
set search_path = public
as $$
  with mine as (
    select m.*,
           case when m.sender_id = auth.uid() then m.receiver_id else m.sender_id end as partner
    from public.pc_messages m
    where m.sender_id = auth.uid() or m.receiver_id = auth.uid()
  ),
  latest as (
    select distinct on (mine.partner) mine.partner, mine.id, mine.body, mine.image_path, mine.sender_id, mine.created_at
    from mine
    order by mine.partner, mine.created_at desc, mine.id desc
  ),
  unread as (
    select mine.sender_id as partner, count(*) as c
    from mine
    where mine.receiver_id = auth.uid() and mine.read_at is null
    group by mine.sender_id
  )
  select l.partner, l.id, l.body, (l.image_path is not null), l.sender_id, l.created_at, coalesce(u.c, 0)
  from latest l
  left join unread u on u.partner = l.partner
  order by l.created_at desc;
$$;

-- Function privileges: nobody by default, then only signed-in users (pc_generate_user_id stays internal).
revoke all on function public.pc_generate_user_id(text)                       from public, anon, authenticated;
revoke all on function public.pc_ensure_profile()                             from public, anon, authenticated;
revoke all on function public.pc_update_profile(text, text, boolean, boolean) from public, anon, authenticated;
revoke all on function public.pc_find_user(text)                              from public, anon, authenticated;
revoke all on function public.pc_add_contact(uuid)                            from public, anon, authenticated;
revoke all on function public.pc_remove_contact(uuid)                         from public, anon, authenticated;
revoke all on function public.pc_list_contacts()                              from public, anon, authenticated;
revoke all on function public.pc_get_profile(uuid)                            from public, anon, authenticated;
revoke all on function public.pc_get_messages(uuid, timestamptz, integer)     from public, anon, authenticated;
revoke all on function public.pc_send_message(uuid, text, text)               from public, anon, authenticated;
revoke all on function public.pc_mark_read(uuid)                              from public, anon, authenticated;
revoke all on function public.pc_heartbeat()                                  from public, anon, authenticated;
revoke all on function public.pc_chat_summaries()                             from public, anon, authenticated;

grant execute on function public.pc_ensure_profile()                             to authenticated;
grant execute on function public.pc_update_profile(text, text, boolean, boolean) to authenticated;
grant execute on function public.pc_find_user(text)                              to authenticated;
grant execute on function public.pc_add_contact(uuid)                            to authenticated;
grant execute on function public.pc_remove_contact(uuid)                         to authenticated;
grant execute on function public.pc_list_contacts()                              to authenticated;
grant execute on function public.pc_get_profile(uuid)                            to authenticated;
grant execute on function public.pc_get_messages(uuid, timestamptz, integer)     to authenticated;
grant execute on function public.pc_send_message(uuid, text, text)               to authenticated;
grant execute on function public.pc_mark_read(uuid)                              to authenticated;
grant execute on function public.pc_heartbeat()                                  to authenticated;
grant execute on function public.pc_chat_summaries()                             to authenticated;

-- ---------------------------------------------------------------- realtime
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables
                     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'pc_messages') then
    alter publication supabase_realtime add table public.pc_messages;
  end if;
end;
$$;

-- ----------------------------------------------------------------- storage
-- New bucket names on purpose: older apps may already have a "chat-media" bucket with looser rules.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('pc-avatars',    'pc-avatars',    true,  2097152, array['image/jpeg', 'image/png', 'image/webp']),
  ('pc-chat-media', 'pc-chat-media', false, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Everyone may only write inside a folder named after their own user id: <uid>/<file>.
drop policy if exists pc_avatars_insert on storage.objects;
create policy pc_avatars_insert on storage.objects for insert to authenticated
with check (bucket_id = 'pc-avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists pc_avatars_select on storage.objects;
create policy pc_avatars_select on storage.objects for select to authenticated
using (bucket_id = 'pc-avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists pc_avatars_delete on storage.objects;
create policy pc_avatars_delete on storage.objects for delete to authenticated
using (bucket_id = 'pc-avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists pc_chat_media_insert on storage.objects;
create policy pc_chat_media_insert on storage.objects for insert to authenticated
with check (bucket_id = 'pc-chat-media' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- A chat photo is readable by its uploader and by the two people in the message that uses it. Nobody else.
drop policy if exists pc_chat_media_select on storage.objects;
create policy pc_chat_media_select on storage.objects for select to authenticated
using (
  bucket_id = 'pc-chat-media'
  and (
    (storage.foldername(name))[1] = (select auth.uid())::text
    or exists (select 1 from public.pc_messages m
               where m.image_path = storage.objects.name
                 and (m.sender_id = (select auth.uid()) or m.receiver_id = (select auth.uid())))
  )
);

-- Make the API pick up the new tables and functions right away.
notify pgrst, 'reload schema';
